Una escuela tiene alumnos duplicados por escribir su nombre y su curso de formas distintas.

function alumnosRepetidos(fichas) {
  const grupos = new Map();
  for (const f of fichas) {
    const nombre = f.nombre.trim().toLowerCase();
    const curso = f.curso.trim().toLowerCase();
    const identificador = nombre + "|" + curso;
    if (!grupos.has(identificador)) {
      grupos.set(identificador, []);
    }
    grupos.get(identificador).push(f.id);
  }
  return [...grupos.values()].filter((ids) => ids.length >= 2);
}
